for (const exercise of exercises) {
  exercise.loadConvention = loadConventions[exercise.code] || 'No externally loaded strength target. Record the prescribed time, repetitions, distance or skill metric.';
  exercise.loadMultiplier = exercise.code === 'ST09' ? 2 : 1;
}

const metadata = {
  ST21:{equipmentConfirmationRequired:true,equipmentNotes:'Confirm a load-rated squat belt on a purpose-built machine or manufacturer-approved attachment. An ordinary lifting belt alone is insufficient.'},
  ST26:{equipmentSupported:['hip flexion'],equipmentNotes:'Use only if the actual model explicitly supports this direction and its pad/pivot setup.'},
  ST27:{equipmentSupported:['hip extension'],equipmentNotes:'Use only if the actual model explicitly supports this direction and its pad/pivot setup.'},
  ST28:{equipmentSupported:['hip abduction'],equipmentNotes:'Use only if the actual model explicitly supports this direction and its pad/pivot setup.'},
  ST29:{equipmentSupported:['hip adduction'],equipmentNotes:'Use only if the actual model explicitly supports this direction and its pad/pivot setup.'},
  ST30:{loggingMode:'machineStrength',equipmentConfirmationRequired:true,loadKg:null,equipmentNotes:'Model unconfirmed. The described equipment could be pneumatic (compressed air) rather than hydraulic. Follow the actual model instructions. Keep feet grounded; no machine jumps are prescribed.',sourceUrls:['https://www.keiser.com/fitness-equipment/strength-training/a300-squat','https://d1xdq93s712gxs.cloudfront.net/media/155504_A_MANUAL__USER_A300-SQUAT_SQUAT-PRO-cinv-170170643150107.pdf']},
  CO07:{defaultLoadKg:0,equipmentNotes:'Check rated slings, attachments and anchor. Slings reduce grip demand but still load the shoulders; stop with pain, tingling or numbness.'},
  PW05:{powerMetric:'throw',sourceUrls:['https://doi.org/10.1519/SSC.0b013e3181e92911','https://www.nsca.com/globalassets/education/nsca-coach/nsca-coach-7.3.pdf']},
  PW06:{powerMetric:'loadedJump',sourceUrls:['https://pmc.ncbi.nlm.nih.gov/articles/PMC6724584/']},
  PW07:{powerMetric:'throw',sourceUrls:['https://doi.org/10.1519/SSC.0b013e3181e92911']},
  SP05:{loggingMode:'machineSpeed',equipmentConfirmationRequired:true,loadKg:null,equipmentNotes:'The chest-supported description resembles a resisted runner such as the Keiser A300, but the model is unconfirmed. This is a machine-specific alternative, not an overground sprint test.',sourceUrls:['https://www.keiser.com/fitness-equipment/strength-training/a300-runner','https://d1xdq93s712gxs.cloudfront.net/media/325500_B_MANUAL__USER_A300-RUNNER-cinv-1769201563168160.pdf']}
};
for (const exercise of exercises) Object.assign(exercise,metadata[exercise.code]||{});

const codes = new Set(exercises.map(e => e.code));
if (codes.size !== exercises.length || exercises.length !== 103) throw new Error('Expected 103 unique canonical exercises');
for (const e of exercises) {
  if (Object.values(e).some(v => typeof v === 'string' && v.includes('\u2014'))) throw new Error('Em dash in '+e.code);
  if (!e.cues.length || !e.mistakes.length || !e.regression || !e.progression) throw new Error('Incomplete definition '+e.code);
}
await mkdir(new URL('../public/data/', import.meta.url), { recursive:true });
await writeFile(new URL('../public/data/exercises.json', import.meta.url), JSON.stringify(exercises,null,2)+'\n');
console.log('Wrote '+exercises.length+' canonical exercise definitions.');
